alter table public.customer_memberships add column if not exists cycle_mode text;
alter table public.customer_memberships add column if not exists renewal_day integer;
alter table public.customer_memberships add column if not exists renewal_shift_days integer not null default 0;
alter table public.membership_cycles add column if not exists sequence_no integer;
update public.membership_cycles mc set sequence_no=q.rn from (select id,row_number() over(partition by membership_id order by cycle_start,created_at,id)::int rn from public.membership_cycles) q where q.id=mc.id and mc.sequence_no is null;
create unique index if not exists membership_cycles_membership_sequence_key on public.membership_cycles(membership_id,sequence_no) where sequence_no is not null;
create or replace function barberium.month_day(p_month date,p_day integer) returns date language sql immutable set search_path='pg_catalog' as $$ select date_trunc('month',p_month)::date + ((least(greatest(coalesce(p_day,1),1),extract(day from (date_trunc('month',p_month)+interval '1 month - 1 day'))::int)-1)::int) $$;
create or replace function barberium.next_renewal_after(p_after date,p_day integer,p_shift integer default 0) returns date language plpgsql immutable set search_path='pg_catalog','barberium' as $$ declare m date; d date; i int:=0; begin m:=date_trunc('month',p_after)::date; loop d:=barberium.month_day(m,p_day)+coalesce(p_shift,0); if d>p_after then return d; end if; m:=(m+interval '1 month')::date; i:=i+1; if i>24 then raise exception 'Não foi possível calcular renovação'; end if; end loop; end $$;
create or replace function barberium.previous_renewal_before(p_before date,p_day integer,p_shift integer default 0) returns date language plpgsql immutable set search_path='pg_catalog','barberium' as $$ declare m date; d date; i int:=0; begin m:=date_trunc('month',p_before)::date; loop d:=barberium.month_day(m,p_day)+coalesce(p_shift,0); if d<p_before then return d; end if; m:=(m-interval '1 month')::date; i:=i+1; if i>24 then raise exception 'Não foi possível calcular renovação anterior'; end if; end loop; end $$;
create or replace function barberium.normalized_cycle_mode(p_rules jsonb) returns text language sql immutable set search_path='pg_catalog' as $$ select case coalesce(p_rules->>'cycle_mode','signup_date') when 'anniversary' then 'signup_date' when 'calendar' then 'calendar_month' when 'calendar_month' then 'calendar_month' when 'fixed_day' then 'fixed_day' else 'signup_date' end $$;
create or replace function barberium.subscription_refresh_one(p_membership_id uuid,p_as_of date default current_date) returns void language plpgsql security definer set search_path='public','barberium','pg_temp' as $$
declare cm record; cyc record; mode text; dayn int; shift int; next_start date; next_end date; grace int; seq int;
begin
 select xcm.*,v.rules into cm from public.customer_memberships xcm join public.membership_plan_versions v on v.id=xcm.plan_version_id where xcm.id=p_membership_id and xcm.plan_type='subscription' for update of xcm;
 if cm.id is null or cm.status in ('cancelled','expired','paused') then return; end if;
 select * into cyc from public.membership_cycles where membership_id=cm.id order by sequence_no desc nulls last,cycle_start desc limit 1 for update; if cyc.id is null then return; end if;
 if cyc.status in ('pending','overdue') then if cyc.status='pending' and cyc.grace_until is not null and p_as_of>cyc.grace_until then update public.membership_cycles set status='overdue' where id=cyc.id; update public.customer_memberships set status='overdue',updated_at=now() where id=cm.id; else update public.customer_memberships set status=cyc.status,updated_at=now() where id=cm.id and status<>cyc.status; end if; return; end if;
 if cyc.status='paid' and p_as_of<=cyc.cycle_end then if cm.status<>'active' then update public.customer_memberships set status='active',updated_at=now() where id=cm.id; end if; return; end if;
 if cyc.status<>'paid' or p_as_of<=cyc.cycle_end then return; end if;
 next_start:=cyc.cycle_end+1;
 if cm.renewal_blocked and cm.cancel_effective_on is not null and next_start>=cm.cancel_effective_on then update public.customer_memberships set status='cancelled',cancelled_at=coalesce(cancelled_at,now()),updated_at=now() where id=cm.id; insert into public.membership_events(membership_id,event_type,details) values(cm.id,'cancelled_effective',jsonb_build_object('effective_on',cm.cancel_effective_on)); return; end if;
 if cm.next_plan_version_id is not null then update public.customer_memberships set plan_id=coalesce(next_plan_id,plan_id),plan_version_id=next_plan_version_id,next_plan_id=null,next_plan_version_id=null,updated_at=now() where id=cm.id; select xcm.*,v.rules into cm from public.customer_memberships xcm join public.membership_plan_versions v on v.id=xcm.plan_version_id where xcm.id=p_membership_id; mode:=barberium.normalized_cycle_mode(cm.rules); dayn:=case mode when 'calendar_month' then 1 when 'fixed_day' then greatest(1,least(31,coalesce(nullif(cm.rules->>'fixed_day','')::int,1))) else coalesce(cm.renewal_day,extract(day from coalesce(cm.started_at,now()))::int) end; update public.customer_memberships set cycle_mode=mode,renewal_day=dayn where id=cm.id; cm.cycle_mode:=mode; cm.renewal_day:=dayn; end if;
 mode:=coalesce(cm.cycle_mode,barberium.normalized_cycle_mode(cm.rules)); dayn:=coalesce(cm.renewal_day,case mode when 'calendar_month' then 1 when 'fixed_day' then greatest(1,least(31,coalesce(nullif(cm.rules->>'fixed_day','')::int,1))) else extract(day from next_start)::int end); shift:=coalesce(cm.renewal_shift_days,0); next_end:=barberium.next_renewal_after(next_start,dayn,shift)-1; if next_end<next_start then next_end:=(next_start+interval '1 month - 1 day')::date; end if; grace:=greatest(0,coalesce(nullif(cm.rules->>'grace_days','')::int,0)); seq:=coalesce(cyc.sequence_no,1)+1;
 insert into public.membership_cycles(membership_id,cycle_start,cycle_end,due_date,grace_until,amount_cents,status,credits_released,paid_at,is_first_cycle,sequence_no) values(cm.id,next_start,next_end,next_start,next_start+grace,(select price_cents from public.membership_plan_versions where id=cm.plan_version_id),'pending',false,null,false,seq) on conflict do nothing;
 update public.customer_memberships set status='pending',current_cycle_start=next_start,current_cycle_end=next_end,cycle_mode=mode,renewal_day=dayn,updated_at=now() where id=cm.id;
 insert into public.membership_events(membership_id,event_type,details) values(cm.id,'renewal_generated',jsonb_build_object('cycle_start',next_start,'cycle_end',next_end,'due_date',next_start,'status','pending'));
end $$;
create or replace function barberium.process_due_subscription_renewals(p_as_of date default current_date) returns integer language plpgsql security definer set search_path='public','barberium','pg_temp' as $$ declare r record; n int:=0; begin for r in select id from public.customer_memberships where plan_type='subscription' and status in ('active','pending','overdue') loop perform barberium.subscription_refresh_one(r.id,p_as_of); n:=n+1; end loop; return n; end $$;
create or replace function barberium.refresh_customer_membership_states(p_customer_id uuid) returns void language plpgsql security definer set search_path='public','barberium','pg_temp' as $$ declare r record; begin for r in select id,paused_until,renewal_blocked,cancel_effective_on from public.customer_memberships where customer_id=p_customer_id and status='paused' and paused_until is not null and paused_until<=current_date for update loop if r.renewal_blocked and r.cancel_effective_on is not null and r.cancel_effective_on<current_date then update public.customer_memberships set status='cancelled',cancelled_at=coalesce(cancelled_at,now()),pause_started_at=null,paused_until=null,updated_at=now() where id=r.id; insert into public.membership_events(membership_id,event_type,details) values(r.id,'cancelled_effective',jsonb_build_object('effective_on',r.cancel_effective_on)); else update public.customer_memberships set status='active',pause_started_at=null,paused_until=null,updated_at=now() where id=r.id; insert into public.membership_events(membership_id,event_type,details) values(r.id,'pause_finished',jsonb_build_object('resumed_on',current_date)); end if; end loop; for r in select id,cancel_effective_on from public.customer_memberships where customer_id=p_customer_id and status in ('active','pending','overdue') and renewal_blocked and cancel_effective_on is not null and cancel_effective_on<current_date for update loop update public.customer_memberships set status='cancelled',cancelled_at=coalesce(cancelled_at,now()),updated_at=now() where id=r.id; insert into public.membership_events(membership_id,event_type,details) values(r.id,'cancelled_effective',jsonb_build_object('effective_on',r.cancel_effective_on)); end loop; for r in select id from public.customer_memberships where customer_id=p_customer_id and plan_type='subscription' and status in ('active','pending','overdue') loop perform barberium.subscription_refresh_one(r.id,current_date); end loop; end $$;
create or replace function public.barberium_staff_assign_membership(p_customer_id uuid,p_plan_id uuid,p_unit_id uuid,p_start_date date default current_date,p_mark_paid boolean default false,p_payment_method text default 'pix') returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$
declare m record; p record; v record; cm_id uuid; cyc_id uuid; cycle_start date; cycle_end date; due date; grace int; first_mode text; amount int; validity text; valid_until date; mode text; dayn int; next_due date; prev_due date; full_days int; used_days int;
begin
 if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null or m.role not in ('owner','admin') then raise exception 'Acesso somente para ADM'; end if; if not exists(select 1 from public.customers where id=p_customer_id and barbershop_id=m.barbershop_id) then raise exception 'Cliente inválido'; end if; select * into p from public.membership_plans where id=p_plan_id and barbershop_id=m.barbershop_id and is_active; if p.id is null then raise exception 'Plano inválido'; end if; select * into v from public.membership_plan_versions where plan_id=p.id and version_no=p.current_version_no;
 if p.plan_type='subscription' then mode:=barberium.normalized_cycle_mode(v.rules); dayn:=case mode when 'calendar_month' then 1 when 'fixed_day' then greatest(1,least(31,coalesce(nullif(v.rules->>'fixed_day','')::int,1))) else extract(day from p_start_date)::int end; first_mode:=coalesce(v.rules->>'first_cycle_mode','full'); if first_mode not in ('full','proportional','custom','next_cycle') then first_mode:='full'; end if; grace:=greatest(0,coalesce(nullif(v.rules->>'grace_days','')::int,0)); amount:=v.price_cents; if mode='signup_date' then cycle_start:=p_start_date; next_due:=barberium.next_renewal_after(cycle_start,dayn,0); cycle_end:=next_due-1; else next_due:=barberium.next_renewal_after(p_start_date-1,dayn,0); if next_due=p_start_date then next_due:=barberium.next_renewal_after(p_start_date,dayn,0); end if; if first_mode='next_cycle' then cycle_start:=next_due; cycle_end:=barberium.next_renewal_after(cycle_start,dayn,0)-1; else cycle_start:=p_start_date; cycle_end:=next_due-1; end if; end if; if first_mode='proportional' and mode<>'signup_date' and cycle_start=p_start_date then prev_due:=barberium.previous_renewal_before(next_due,dayn,0); full_days:=greatest(1,next_due-prev_due); used_days:=greatest(1,next_due-p_start_date); amount:=round(v.price_cents*(used_days::numeric/full_days))::int; elsif first_mode='custom' then amount:=greatest(0,coalesce(nullif(v.rules->>'first_cycle_custom_amount_cents','')::int,v.price_cents)); end if; due:=cycle_start; insert into public.customer_memberships(barbershop_id,customer_id,plan_id,plan_version_id,plan_type,origin_unit_id,status,started_at,current_cycle_start,current_cycle_end,created_by_member_id,cycle_mode,renewal_day,renewal_shift_days) values(m.barbershop_id,p_customer_id,p.id,v.id,p.plan_type,p_unit_id,'pending',null,cycle_start,cycle_end,m.member_id,mode,dayn,0) returning id into cm_id; insert into public.membership_cycles(membership_id,cycle_start,cycle_end,due_date,grace_until,amount_cents,status,credits_released,paid_at,is_first_cycle,sequence_no) values(cm_id,cycle_start,cycle_end,due,due+grace,amount,'pending',false,null,true,1) returning id into cyc_id;
 else validity:=coalesce(v.rules->>'credit_validity','no_expiry'); valid_until:=case when validity='fixed_days' then p_start_date+greatest(1,coalesce((v.rules->>'fixed_validity_days')::int,30)) else null end; insert into public.customer_memberships(barbershop_id,customer_id,plan_id,plan_version_id,plan_type,origin_unit_id,status,started_at,valid_until,created_by_member_id) values(m.barbershop_id,p_customer_id,p.id,v.id,p.plan_type,p_unit_id,'pending',null,valid_until,m.member_id) returning id into cm_id; end if; insert into public.membership_events(membership_id,event_type,details,actor_member_id) values(cm_id,'created',jsonb_build_object('paid',false,'plan_version_id',v.id,'payment_required_full',true),m.member_id); if p_mark_paid then perform public.barberium_staff_record_membership_payment(cm_id,cyc_id,p_payment_method); end if; return jsonb_build_object('ok',true,'membership_id',cm_id,'cycle_id',cyc_id,'status',case when p_mark_paid then 'active' else 'pending' end); exception when unique_violation then raise exception 'Cliente já possui um plano deste tipo ativo'; end $$;

